<?php
/**
 * GiftAura - staff administrators.
 *
 * Two kinds of administrator:
 *   - role 'admin' = SUPER ADMINISTRATOR (the owner). Full access, created
 *     only with scripts/create_admin.php. Manages staff accounts.
 *   - role 'staff' = STAFF ADMINISTRATOR, created by the super administrator
 *     in Admin -> Staff accounts. Logs in with a username and a password
 *     generated by the system, must choose a new password at first login,
 *     and can only open the areas ticked for them (PERMISSIONS).
 *
 * Always super-admin only: Staff accounts, Settings, E-mail log, Activity log.
 */
declare(strict_types=1);

final class StaffService
{
    /** Areas a staff member can be given: key => [label, explanation]. */
    public const PERMISSIONS = [
        'products'   => ['Products and stock', 'Add and edit products, photos, prices, personalisation and stock (Products, Inventory)'],
        'categories' => ['Categories', 'Add and edit main categories, subcategories, pictures and Popular categories'],
        'inquiries'  => ['Customer inquiries', 'Read and answer messages sent from the Contact page'],
        'orders'     => ['Orders and payments', 'View orders, change order status and record payments'],
        'shop_sales' => ['In-shop sales (invoices)', 'Sell products to customers who visit the shop, print invoices (stock is reduced automatically)'],
        'customers'  => ['Customers', 'View customer accounts, deactivate them and set temporary passwords'],
        'reviews'    => ['Reviews', 'Hide, show and delete product reviews'],
        'content'    => ['Banners and About page', 'Homepage banners and the texts of the About page'],
        'reports'    => ['Reports and sales figures', 'Sales reports, CSV export and the sales figures on the dashboard'],
    ];

    /** Ticked for a new staff member until the super administrator changes them. */
    public const DEFAULT_PERMISSIONS = ['products', 'categories', 'inquiries'];

    private const PASSWORD_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789';

    /** Clean list of known permission keys from a form or the database. */
    public static function cleanPermissions(mixed $value): array
    {
        $list = is_array($value) ? $value : explode(',', (string) $value);
        $list = array_map(static fn($v) => trim((string) $v), $list);
        return array_values(array_intersect(array_keys(self::PERMISSIONS), $list));
    }

    /** Every panel user (super administrators first). */
    public static function all(): array
    {
        return Database::fetchAll(
            "SELECT u.id, u.role, u.full_name, u.username, u.email, u.permissions, u.is_active, u.must_change_password,
                    u.last_login_at, u.created_at, c.full_name AS created_by_name
               FROM users u LEFT JOIN users c ON c.id = u.created_by
              WHERE u.role IN ('admin', 'staff')
              ORDER BY (u.role = 'admin') DESC, u.is_active DESC, u.full_name"
        );
    }

    public static function findStaff(int $id): ?array
    {
        return Database::fetchOne("SELECT * FROM users WHERE id = :id AND role = 'staff'", ['id' => $id]);
    }

    /** A random 12-character password with upper case, lower case and digits (no 0/O, 1/l/I). */
    public static function generatePassword(int $length = 12): string
    {
        do {
            $password = '';
            for ($i = 0; $i < $length; $i++) {
                $password .= self::PASSWORD_ALPHABET[random_int(0, strlen(self::PASSWORD_ALPHABET) - 1)];
            }
        } while (!preg_match('/[A-Z]/', $password) || !preg_match('/[a-z]/', $password) || !preg_match('/\d/', $password));
        return $password;
    }

    /**
     * Validate name, username, e-mail and permissions.
     * Returns [errors, cleanValues].
     */
    private static function validate(array $input, ?int $exceptId, bool $isNew): array
    {
        $errors = [];
        $name = trim((string) ($input['full_name'] ?? ''));
        $username = mb_strtolower(trim((string) ($input['username'] ?? '')));
        $email = mb_strtolower(trim((string) ($input['email'] ?? '')));
        $permissions = self::cleanPermissions($input['permissions'] ?? []);

        if (mb_strlen($name) < 2 || mb_strlen($name) > 100) {
            $errors['full_name'] = 'Enter the staff member\'s name (2–100 characters).';
        }
        if ($isNew) {
            if (!preg_match('/^[a-z0-9][a-z0-9._-]{2,29}$/', $username)) {
                $errors['username'] = 'Use 3–30 characters: lower-case letters, numbers, dot, dash or underscore, e.g. nimal.staff';
            } elseif (Database::fetchValue('SELECT 1 FROM users WHERE username = :u', ['u' => $username]) !== null) {
                $errors['username'] = 'This username is already taken.';
            }
        }
        if ($email !== '') {
            if (!filter_var($email, FILTER_VALIDATE_EMAIL) || mb_strlen($email) > 190) {
                $errors['email'] = 'Enter a valid e-mail address, or leave it empty.';
            } elseif (Database::fetchValue('SELECT 1 FROM users WHERE email = :e AND id <> :id', ['e' => $email, 'id' => $exceptId ?? 0]) !== null) {
                $errors['email'] = 'Another account already uses this e-mail address.';
            }
        }
        if ($permissions === []) {
            $errors['permissions'] = 'Tick at least one area this staff member may work in.';
        }
        return [$errors, ['full_name' => $name, 'username' => $username, 'email' => $email, 'permissions' => $permissions]];
    }

    /**
     * Create a staff administrator. Returns ['id' => int, 'password' => generated password]
     * or ['errors' => [...], 'old' => [...]]. The password is shown ONCE to the super
     * administrator and stored only as a hash.
     */
    public static function create(array $input, int $adminId): array
    {
        [$errors, $v] = self::validate($input, null, true);
        if ($errors !== []) {
            return ['errors' => $errors, 'old' => $v];
        }
        $password = self::generatePassword();
        try {
            $id = Database::insert(
                "INSERT INTO users (role, full_name, email, username, password_hash, permissions, must_change_password, created_by, email_verified_at)
                 VALUES ('staff', :name, :email, :username, :hash, :perms, 1, :by, :verified)",
                [
                    'name' => $v['full_name'], 'email' => $v['email'] !== '' ? $v['email'] : null, 'username' => $v['username'],
                    'hash' => password_hash($password, PASSWORD_DEFAULT), 'perms' => implode(',', $v['permissions']),
                    'by' => $adminId, 'verified' => $v['email'] !== '' ? date('Y-m-d H:i:s') : null,
                ]
            );
        } catch (PDOException $e) {
            if ($e->getCode() === '23000') {
                return ['errors' => ['username' => 'This username or e-mail is already taken.'], 'old' => $v];
            }
            throw $e;
        }
        ActivityLogService::log($adminId, 'staff.create', 'user', $id,
            $v['full_name'] . ' (' . $v['username'] . '): ' . implode(', ', $v['permissions']));
        return ['id' => $id, 'password' => $password];
    }

    /** Change name, e-mail and permissions of a staff member. Returns [] or errors. */
    public static function update(int $id, array $input, int $adminId): array
    {
        $staff = self::findStaff($id);
        if ($staff === null) {
            return ['full_name' => 'Staff account not found.'];
        }
        [$errors, $v] = self::validate($input, $id, false);
        if ($errors !== []) {
            return $errors;
        }
        Database::execute(
            'UPDATE users SET full_name = :name, email = :email, permissions = :perms WHERE id = :id AND role = \'staff\'',
            ['name' => $v['full_name'], 'email' => $v['email'] !== '' ? $v['email'] : null, 'perms' => implode(',', $v['permissions']), 'id' => $id]
        );
        $before = self::cleanPermissions($staff['permissions']);
        ActivityLogService::log($adminId, 'staff.update', 'user', $id, $v['full_name']
            . ($before !== $v['permissions'] ? ': permissions ' . implode(', ', $before) . ' -> ' . implode(', ', $v['permissions']) : ''));
        return [];
    }

    /** New generated password (shown once); the staff member must change it at next login. */
    public static function resetPassword(int $id, int $adminId): ?string
    {
        $staff = self::findStaff($id);
        if ($staff === null) {
            return null;
        }
        $password = self::generatePassword();
        Database::execute(
            "UPDATE users SET password_hash = :h, must_change_password = 1 WHERE id = :id AND role = 'staff'",
            ['h' => password_hash($password, PASSWORD_DEFAULT), 'id' => $id]
        );
        ActivityLogService::log($adminId, 'staff.password_reset', 'user', $id, $staff['full_name'] . ' (password not logged)');
        return $password;
    }

    /** Deactivate (logs the person out at once) or reactivate a staff account. */
    public static function setActive(int $id, bool $active, int $adminId): bool
    {
        $staff = self::findStaff($id);
        if ($staff === null) {
            return false;
        }
        Database::execute("UPDATE users SET is_active = :a WHERE id = :id AND role = 'staff'", ['a' => $active ? 1 : 0, 'id' => $id]);
        ActivityLogService::log($adminId, $active ? 'staff.activate' : 'staff.deactivate', 'user', $id, $staff['full_name']);
        return true;
    }
}
